SELECT status, DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, CASE WHEN balance >= 83000 THEN 'high' WHEN balance >= 8000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(CASE WHEN account_type = 'SAVINGS' THEN balance ELSE 0 END) AS savings_balance, COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END) AS loan_count FROM accounts GROUP BY status, opened_month, balance_bucket HAVING COUNT(DISTINCT balance) >= 2 ORDER BY 4
